-- public.enchant_more(p_world uuid, p_uid uuid, p_tool text, p_effect text, p_item text, p_ql double precision, p_what text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.enchant_more(p_world uuid, p_uid uuid, p_tool text, p_effect text, p_item text, p_ql double precision, p_what text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare v_name text;
begin
  select e.name into v_name from job_tool(p_world, p_uid, p_tool) t join enchantments() e on e.id = t.enchant->>'id' and e.effect = p_effect;
  if v_name is null or not random() < tool_enchant(p_world, p_uid, p_tool, p_effect) then return; end if;
  perform gather(p_world, p_uid, p_item, 1, p_ql);
  perform tell(p_world, p_uid, v_name || ' brings one more of the '
    || coalesce(p_what, lower((select coalesce(name, p_item) from item_def where id = p_item))) || '.', 'event');
end $function$
